IF
Combined(S_GOB_GoblinToast_BeerSkullTub_43d2f409-e9cb-4bbe-974c-b1e2cce87562,_,_,_,_,_Player,_NewTub)
AND
DB_GOB_GoblinToast_OwnersCached(_OrigOwner,_Owner)
THEN
NOT DB_GOB_GoblinToast_Tub(S_GOB_GoblinToast_BeerSkullTub_43d2f409-e9cb-4bbe-974c-b1e2cce87562);
DB_GOB_GoblinToast_Tub(_NewTub);
SetOriginalOwner(_NewTub,_OrigOwner);
SetOwner(_NewTub,_Owner);

IF
EnteredTrigger(_Char, _Ring)
AND
NOT DB_SHA_Crypt_RingsDisabled(1)
AND
DB_SHA_Crypt_Rings(_Ring)
AND
NOT DB_SHA_Crypt_BlockExplosionFor(_Char)
THEN
RealtimeObjectTimerLaunch(_Char, "SHA_Rings_Explosion", 4000);
DB_SHA_Crypt_BlockExplosionFor(_Char);
DB_SHA_Crypt_PushedBy(_Char, _Ring);
CreateExplosion(S_SHA_EntrancePuzzle_PushBackOrigin_6033bf61-df5e-44e8-b387-217513235179, "Projectile_SHA_EntrancePuzzle_RingPushBack", -1, S_SHA_Crypt_TrapDefuser_03ba50b7-b34d-4416-9e90-72d6d8bb08c4);
